  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "明确线性层的数据移动动机、M/K/N 轴、含 bias/旧输出/激活/转换的函数、各精度边界和字节单位；输出所有权、部分归约、发布及空维度语义完整。",
      "evidence": [
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "Y[m,n]=Convert_y(φ(Σ_k X[m,k]W[k,n]+b[n]+βY_old[m,n]))。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "一次输出块的状态为：取得独占写权 → 输入 panel 就绪 → K 归约部分完成 → 完整归约后执行 epilogue → 输出发布。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "区分地址、别名、覆盖、完成可见性和单次 epilogue 等必要条件与布局、向量化、打包及划分选择。零填充限定于对应表示和有限精确算术，没有将归约重排推广为浮点逐位等价。",
      "evidence": [
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "加载掩码与最终 store 掩码各自必要，不能用正确 store 掩盖此前越界读取。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "改变分块、FMA、归约树、线程合并顺序或累加精度可能改变浮点结果。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "三个伪代码算法均具有初始化、推进、边界和完成条件。复核打包索引后，微块超出宏块的位置保持零且最终写回受宏块边界限制；Cacc 与寄存器 R 的状态区分正确。沿 K 的 GEMV 包含水平合并；split-K 同时要求完整分段身份、读取可见性和合并后的单次输出处理。",
      "evidence": [
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "idx_Xp(i,q)=(floor(i/m_r)k_c+q)m_r+(i mod m_r)，"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "这里 Cacc 是内存中的宏块状态，只有当前 R 是寄存器状态。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "等待全部 P 份不同的完成记录，建立部分矩阵读取可见性"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "执行乘加量与所给补齐循环一致，源读取次数与宏块重打包顺序一致，Cacc 交通包含清零、逐 panel 往返和最终有效读取。区分逻辑请求、scratch 交通、下层事务、容量与关键路径；split-K、准备摊销、NUMA 和版本共存均有条件化账目。复算两个强度、带宽单位及 128/124 页边界正确；Goto 因子 2 的适用条件与原文一致。",
      "evidence": [
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "F_exec=2·ceil(M/m_c)·ceil(N/n_c)·ceil(K/k_c)·m̂·n̂·k_c。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "D_Cacc=[(1+2Q)B_MB_Nm̂n̂+MN]s_acc。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "若源读已包含在 L_X/L_W 中，汇总同一层交通时只补充尚未计入的目的写与后续读取，不能再把完整 2B 复制流量重复相加。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "条件变化表保持函数、覆盖和身份关系，针对形状、复用、页布局、dtype、NUMA、并发及 β 重算对应成本，并给出放弃预打包、减少线程或避免 split-K 的反转条件；服务场景没有直接继承离线最优线程数。",
      "evidence": [
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "固定权重长期复用可以摊销打包，但格式频繁变化或部署寿命短时选择可能反转。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "应固定总 CPU 预算比较请求并行与算子并行，并把等待和尾延迟纳入决策，不能继承离线单调用的最佳线程数。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "给出带宽、同步、TLB、spill、准备和服务排队的竞争解释、干预预测与反证修正。原漏段失败被正确定位为抵消导致数值比较失去检测能力；修订保留原输入，并用实际消费覆盖、完成身份及非零贡献见证互补检测。计数器范围和未测硬件边界声明准确。",
      "evidence": [
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "正确修复是保留这个抵消反例，以实际消费的 k 次数和分段身份检出缺失，再用非零贡献用例确认数值比较器能够拒绝漏段。"
        },
        {
          "path": "knowledge/hardware/cpu-linear-kernels.md",
          "quote": "页集合和相关事件不变时，不能继续只归因 TLB"
        }
      ]
    }
  },
